export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, AjvValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : compileSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool, name);
    if (!validate(input)) {
      const issues = formatValidationErrors(validate.errors);
      log.warn('tool', 'input validation failed', {name, issues});
      const summary =
        issues.length > 0 ? `Invalid input for tool "${name}": ${issues.join('; ')}` : `Invalid input for tool "${name}"`;
      return {result: summary};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(tool: StoredTool, name: string): AjvValidateFunction {
    if (tool.validate) {
      return tool.validate;
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) {
      return cached;
    }
    const compiled = compileSchema(name, definition.inputSchema);
    this.dynamicValidators.set(definition.inputSchema, compiled);
    return compiled;
  }
}

function formatValidationErrors(errors?: AjvValidationError[] | null): string[] {
  if (!errors || errors.length === 0) return [];
  return errors.map(formatValidationError);
}

function formatValidationError(error: AjvValidationError): string {
  const basePath = formatFieldPath(error.instancePath ?? error.dataPath);
  if (error.keyword === 'required') {
    const missing = typeof error.params.missingProperty === 'string' ? error.params.missingProperty : '';
    const field = basePath ? `${basePath}.${missing}` : missing;
    return `missing required property "${field}"`;
  }
  const target = basePath || '(root)';
  if (error.keyword === 'type') {
    const rawType = error.params.type;
    const expected = Array.isArray(rawType) ? rawType.join(' | ') : String(rawType);
    return `property "${target}" must be ${expected}`;
  }
  const allowedValues = error.params.allowedValues;
  if (error.keyword === 'enum' && Array.isArray(allowedValues)) {
    const allowed = allowedValues.map((entry: unknown) => JSON.stringify(entry)).join(', ');
    return `property "${target}" must be one of: ${allowed}`;
  }
  const detail = error.message ?? `failed ${error.keyword} validation`;
  return `property "${target}" ${detail}`;
}

function formatFieldPath(rawPath?: string): string {
  if (!rawPath) return '';
  return rawPath.replace(/^[/.]/, '').replace(/\//g, '.');
}

function compileSchema(toolName: string, schema: Record<string, unknown>): AjvValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`, {cause: error});
  }
}

